import json, os, subprocess, sys, time

# MUST run before torch is imported anywhere.
#
# Kaggle's API only exposes an `enable_gpu` boolean, with no way to request a
# card, and it consistently allocates a Tesla P100. P100 is sm_60; the stock
# build here is torch 2.10.0+cu128, whose arch list is sm_70..sm_120. The
# mismatch is not a warning -- every CUDA op raises
# "no kernel image is available for execution on the device".
#
# Measured fix: torch 2.4.1+cu121 ships sm_50..sm_90 and runs on this card.
# transformers is pinned alongside it because the stock transformers expects a
# much newer torch; 4.44.2 is the oldest release with Gemma-2 support.
_gpu = subprocess.run(["nvidia-smi", "--query-gpu=name", "--format=csv,noheader"],
                      capture_output=True, text=True).stdout.strip()
print("allocated GPU:", _gpu)
if "P100" in _gpu or "K80" in _gpu:
    print("pre-Volta card: installing a torch build that targets sm_60...")
    subprocess.run([sys.executable, "-m", "pip", "install", "-q",
                    "torch==2.4.1", "--index-url",
                    "https://download.pytorch.org/whl/cu121"], check=True, timeout=2400)
    subprocess.run([sys.executable, "-m", "pip", "install", "-q",
                    "transformers==4.44.2"], check=True, timeout=1200)
    import importlib
    importlib.invalidate_caches()

import numpy as np

# Weights come from Kaggle's own mounted copy of Gemma-2, so no credential is
# needed and none is ever written into this file. A Hugging Face token is used
# only if one happens to be attached as a Kaggle secret AND the mount is absent;
# pushing a new kernel version resets secret attachments, so the mount is the
# path that actually survives an unattended loop.
import glob
# The mount nests a version directory under the variation, so the model root is
# wherever config.json actually is -- globbing the variation returned ['2'].
MODEL_PATH = None
_configs = [c for c in glob.glob("/kaggle/input/**/config.json", recursive=True)
            if "gemma" in c.lower()]
if _configs:
    MODEL_PATH = os.path.dirname(sorted(_configs, key=len)[0])
else:
    print("kaggle/input tree:", glob.glob("/kaggle/input/*"))

if MODEL_PATH:
    print("using Kaggle-mounted weights:", MODEL_PATH)
    print("  contents:", sorted(os.listdir(MODEL_PATH))[:12])
else:
    try:
        from kaggle_secrets import UserSecretsClient
        os.environ["HF_TOKEN"] = UserSecretsClient().get_secret("HF_TOKEN")
        MODEL_PATH = "google/gemma-2-2b"
        print("no mount found; falling back to Hugging Face with a Kaggle secret")
    except Exception as exc:
        raise SystemExit(
            f"no Gemma weights: mount missing and no HF_TOKEN secret ({type(exc).__name__}). "
            "Attach the model google/gemma-2/transformers/gemma-2-2b to this kernel.")

# The contract names a specific model. Verify the mounted weights are that
# model before spending an hour on them: a different Gemma variant would
# produce embeddings that look fine and score badly for no visible reason.
import json as _json
_cfg_path = os.path.join(str(MODEL_PATH), "config.json")
if os.path.exists(_cfg_path):
    _cfg = _json.load(open(_cfg_path))
    print("config:", {k: _cfg.get(k) for k in
                      ("model_type", "hidden_size", "num_hidden_layers",
                       "vocab_size", "intermediate_size")})
    assert _cfg.get("model_type") == "gemma2", f"expected gemma2, got {_cfg.get('model_type')}"
    assert _cfg.get("hidden_size") == 2304, f"hidden_size {_cfg.get('hidden_size')} != 2304"
    assert _cfg.get("num_hidden_layers") == 26, f"layers {_cfg.get('num_hidden_layers')} != 26"
    print("contract check: gemma2, 2304 hidden, 26 layers -- matches google/gemma-2-2b")
    print("weight files:", sorted(f for f in os.listdir(MODEL_PATH)
                                  if f.endswith((".safetensors", ".bin")))[:8])
else:
    raise SystemExit(f"no config.json under {MODEL_PATH}; cannot verify the contract")

import torch
print("torch", torch.__version__, "| arch list", torch.cuda.get_arch_list())
if not torch.cuda.is_available():
    raise SystemExit("no GPU: enable the GPU accelerator on this kernel")
_cap = torch.cuda.get_device_capability(0)
print("gpu", torch.cuda.get_device_name(0), _cap)
# Fail here, in one second, rather than after the corpus build and a partial
# extraction: a card outside the build's arch list raises on every CUDA op.
_arch = f"sm_{_cap[0]}{_cap[1]}"
if _arch not in torch.cuda.get_arch_list():
    raise SystemExit(f"{_arch} is not in this torch build's arch list "
                     f"{torch.cuda.get_arch_list()} -- every CUDA op would fail")
torch.zeros(4, device="cuda").sum().item()  # proves a kernel actually launches
print("CUDA smoke test passed")


"""New public contrastive corpus and offline teacher-agreement experiment.

The teacher is used only to filter training rows. Evaluation retains original
labels, including disagreements. ParaDetox may share ancestry with Wikipedia
and Civil Comments; these families are excluded from its transfer evidence.
"""
import gc
import glob
import hashlib
import json
import os
import re
import sys
from pathlib import Path

import numpy as np
from probe.corpus import canonical_text, _balance
from probe.extract import extract, save_bundle
from probe.finalize import fit_head
from probe.select import Recipe, resample_to_prior, _stratified_cap, auroc, quota_accuracy
from probe.submission import build_and_verify


def run(model_path, cap=3000):
    import torch
    from datasets import load_dataset
    from transformers import AutoTokenizer, AutoModelForSequenceClassification
    from huggingface_hub import model_info

    out = Path('/kaggle/working')
    corpus_path = Path(glob.glob('/kaggle/input/**/corpus.jsonl', recursive=True)[0])
    records = [json.loads(line) for line in corpus_path.read_text().splitlines() if line.strip()]
    # A stricter overlap key collapses punctuation and case differences too.
    key = lambda t: re.sub(r'\W+', '', str(t).casefold())
    seen = {key(r['text']) for r in records}
    pool = []
    duplicates = 0
    ds = load_dataset('s-nlp/paradetox', split='train')
    for row in ds:
        for field, label in [('en_toxic_comment', 1), ('en_neutral_comment', 0)]:
            text = row[field].strip()
            k = key(text)
            if k in seen:
                duplicates += 1
                continue
            seen.add(k)
            if len(text) >= 3:
                pool.append((text, label))
    chosen = _balance(pool, cap, 0.5)
    assert len(chosen) == cap and sum(y for _, y in chosen) == cap // 2
    manifest = {'dataset': 's-nlp/paradetox', 'fingerprint': ds._fingerprint,
                'revision': ds.info.version.__str__(), 'raw_pairs': len(ds),
                'new_rows': len(chosen), 'excluded_duplicates': duplicates,
                'labels': {'en_toxic_comment': 1, 'en_neutral_comment': 0},
                'excluded_transfer_families': ['civil', 'wiki'],
                'note': 'New candidate corpus, not identified as competition source.'}
    (out/'new_corpus.jsonl').write_text(''.join(json.dumps({'text':t,'label':y,'source':'paradetox'})+'\n' for t,y in chosen))
    print('NEW_CORPUS', json.dumps(manifest), flush=True)
    xx = extract([t for t,_ in chosen], '/kaggle/temp/paradetox_l14.npy',
                 model_id=model_path, batch_size=64)
    save_bundle(out/'paradetox_l14.npz', xx, np.array([y for _,y in chosen]),
                ['paradetox']*len(chosen), families=['paradetox']*len(chosen))
    del xx
    gc.collect()
    torch.cuda.empty_cache()

    # Use an explicitly pinned public model revision; never treat teacher
    # confidence as ground truth or filter any held-out evaluation rows.
    teacher = 'unitary/toxic-bert'
    revision = model_info(teacher).sha
    tok = AutoTokenizer.from_pretrained(teacher, revision=revision)
    model = AutoModelForSequenceClassification.from_pretrained(teacher, revision=revision).to('cuda').eval()
    names = {int(i):str(s).lower() for i,s in model.config.id2label.items()}
    indexes = [i for i,s in names.items() if s in ('toxic', 'toxicity')]
    assert len(indexes) == 1, names
    scores = np.zeros(len(records), dtype=np.float32)
    ordered = sorted(range(len(records)), key=lambda i:len(records[i]['text']))
    for start in range(0, len(ordered), 64):
        idx = ordered[start:start+64]
        inp = tok([records[i]['text'] for i in idx], padding=True, truncation=True,
                  max_length=128, return_tensors='pt').to('cuda')
        with torch.inference_mode():
            pred = model(**inp).logits.sigmoid()[:,indexes[0]].cpu().numpy()
        scores[idx] = pred
        if start % 12800 == 0:
            print(f'TEACHER {start}/{len(records)}', flush=True)
    np.save(out/'teacher_scores.npy', scores)
    manifest['teacher'] = {'model':teacher,'revision':revision,'max_length':128,
                           'label_mapping':names,'corpus_sha256':hashlib.sha256(corpus_path.read_bytes()).hexdigest()}
    (out/'new_corpus_manifest.json').write_text(json.dumps(manifest, indent=1))
    print('TEACHER_CORPUS_OK', flush=True)


run(MODEL_PATH, cap=3000)
